/*
 * prog20_anagram_checker – reconstructed from the obfuscated binary
 *
 * Behaviour (exactly matches the original binary):
 *
 *   1. If the program is started with fewer than two arguments
 *      (i.e. argc < 3) it prints the literal string "USAGE".
 *
 *   2. If either of the two supplied strings is 1024 characters
 *      long or longer it prints "TOO_LONG".
 *
 *   3. Otherwise the program checks whether the two strings are
 *      anagrams of each other with the following rules:
 *
 *        • Upper‑case letters are treated case‑insensitively
 *          (they are converted to lower‑case before counting).
 *
 *        • The space character (' ') is completely ignored – it is
 *          **not** counted in either string.
 *
 *        • All other byte values (digits, punctuation, other
 *          whitespace, non‑ASCII bytes, etc.) are counted exactly
 *          as they appear.
 *
 *      The two strings are anagrams iff the frequency of every
 *      possible byte value (0‑255) is identical in the two strings.
 *
 *   4. If they are anagrams the program prints "ANAGRAM",
 *      otherwise it prints "NOT_ANAGRAM".
 *
 *   The program always returns 0.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char *argv[])
{
    /* --------------------------------------------------------------
     * 1. Argument validation
     * -------------------------------------------------------------- */
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    /* 2. Length limit (the original binary rejects strings of length
     *    1024 or more). */
    if (strlen(argv[1]) >= 1024 || strlen(argv[2]) >= 1024) {
        puts("TOO_LONG");
        return 0;
    }

    /* --------------------------------------------------------------
     * 3. Frequency counting (case‑insensitive, spaces ignored)
     * -------------------------------------------------------------- */
    int cnt1[256] = {0};
    int cnt2[256] = {0};

    for (const unsigned char *p = (const unsigned char *)argv[1]; *p; ++p) {
        unsigned char c = *p;
        if (c == ' ')               /* spaces are ignored */
            continue;
        if (isupper(c))             /* case‑insensitive for letters */
            c = (unsigned char)tolower(c);
        cnt1[c]++;                  /* count the (possibly lowered) byte */
    }

    for (const unsigned char *p = (const unsigned char *)argv[2]; *p; ++p) {
        unsigned char c = *p;
        if (c == ' ')               /* spaces are ignored */
            continue;
        if (isupper(c))
            c = (unsigned char)tolower(c);
        cnt2[c]++;
    }

    /* --------------------------------------------------------------
     * 4. Comparison
     * -------------------------------------------------------------- */
    const char *msg = "ANAGRAM";
    for (int i = 0; i < 256; ++i) {
        if (cnt1[i] != cnt2[i]) {
            msg = "NOT_ANAGRAM";
            break;
        }
    }

    puts(msg);
    return 0;
}
